    return Array.from(document.querySelectorAll('.result')).map(r => ({
      title: r.querySelector('.result__title')?.innerText.trim(),
      snippet: r.querySelector('.result__snippet')?.innerText.trim(),
      url: r.querySelector('a.result__url')?.href,
      actualUrl: r.querySelector('.result__title a')?.href
    })).filter(r => r.title && r.snippet);
  });

  await tool.tabs_close({ tabId: sTabId });
  return results;
};

