function decodeDDG(u) {
  const match = u.match(/uddg=([^&]+)/);
  return match ? decodeURIComponent(match[1]) : u;
}

// Let's search DDG for Houston, Miami, Seattle, and LA job postings
const searchDDG = async (query) => {
  const sTab = await tool.tabs_create({ url: `https://html.duckduckgo.com/html/?q=${encodeURIComponent(query)}` });
  const sTabId = sTab.details.tabId;
  await tool.wait_for({ tabId: sTabId, condition: "load_state", value: "domcontentloaded", timeout_ms: 15000 });

  const results = await browserjs(sTabId, () => {
    return Array.from(document.querySelectorAll('.result')).map(r => ({
      title: r.querySelector('.result__title')?.innerText.trim(),
      snippet: r.querySelector('.result__snippet')?.innerText.trim(),
      rawUrl: r.querySelector('.result__title a')?.href
    })).filter(r => r.title && r.snippet);
  });

  await tool.tabs_close({ tabId: sTabId });
  return results.map(r => ({ ...r, url: decodeDDG(r.rawUrl) }));
};

